<script setup lang="ts">import {Head,Link,useForm} from '@inertiajs/vue3';const props=defineProps<{content:any}>();const form=useForm({...props.content,faq:[...(props.content.faq||[])]});const addFaq=()=>form.faq.push({question:'',answer:''});</script>
<template><Head title="Konten Landing"/><main class="min-h-screen bg-slate-100 p-5"><form @submit.prevent="form.put('/admin/landing')" class="mx-auto max-w-3xl space-y-5 rounded-2xl bg-white p-7"><Link href="/admin/dashboard" class="text-emerald-700">← Dashboard</Link><h1 class="text-3xl font-bold text-emerald-950">Konten landing</h1><label class="block">Judul hero<input v-model="form.hero_title" class="mt-1 w-full rounded-xl border-slate-300"/></label><label class="block">Deskripsi<textarea v-model="form.hero_description" rows="4" class="mt-1 w-full rounded-xl border-slate-300"></textarea></label><label class="block">Persyaratan<textarea v-model="form.requirements" rows="6" class="mt-1 w-full rounded-xl border-slate-300"></textarea></label><label class="block">Kontak<textarea v-model="form.contact" rows="3" class="mt-1 w-full rounded-xl border-slate-300"></textarea></label><fieldset><legend class="font-bold">FAQ</legend><div v-for="(item,i) in form.faq" :key="i" class="mt-3 grid gap-2 rounded-xl border p-4"><input v-model="item.question" placeholder="Pertanyaan" class="rounded-lg border-slate-300"/><textarea v-model="item.answer" placeholder="Jawaban" class="rounded-lg border-slate-300"></textarea><button type="button" @click="form.faq.splice(i,1)" class="text-left text-sm text-red-700">Hapus</button></div><button type="button" @click="addFaq" class="mt-3 rounded-lg border px-3 py-2">Tambah FAQ</button></fieldset><button class="w-full rounded-xl bg-emerald-800 py-3 font-bold text-white">Simpan konten</button></form></main></template>
